def summarize():
    buyers = set()
    sellers = set()
    equilibrium = None
    while buyers and sellers:
        buyer = buyers.pop()
        seller = sellers.pop()
        if buyer == seller:
            continue
        if buyer == equilibrium:
            continue
        if seller == equilibrium:
            continue
        if buyer < seller:
            equilibrium = buyer
            sellers.add(equilibrium)
        else:
            equilibrium = seller
            buyers.add(equilibrium)
    return equilibrium
